const m = $('Merge Context').first().json;
const text = String(m.last_line || m.texto || '').replace(/\n?__cw_in_reply_to__:\S+/g, '').trim();
const pre = `Estado actual: ${m.estado || 'idle'}\nBoton: ${m.boton_id || 'none'}\nTexto: ${text}`;
return [{ json: { ...m, classify_input: pre } }];

const base = $('Merge Context').first().json;
const raw = String($input.first().json.text || $input.first().json.response || '').trim();
let parsed = { intent: 'other', confidence: 0 };
const m = raw.match(/\{[\s\S]*\}/);
if (m) {
  try {
    const j = JSON.parse(m[0]);
    const intent = String(j.intent || 'other').toLowerCase();
    const conf = Number(j.confidence || 0);
    if (['cancelar','reprogramar','estudio_precio','other'].includes(intent)) parsed.intent = intent;
    parsed.confidence = Number.isFinite(conf) ? Math.max(0, Math.min(1, conf)) : 0;
  } catch (e) {}
}
return [{ json: { ...base, ai_intent: parsed.intent, ai_confidence: parsed.confidence, ai_raw: raw } }];

const item = $input.first().json;
let estado = item.estado || 'idle';
let boton = String(item.boton_id || '').trim();
const texto = String(item.texto || '').trim();
const lines = texto.split(/\r?\n/).map(x => x.trim()).filter(Boolean);
const last = lines.length ? lines[lines.length - 1] : texto;
const lastLower = last.toLowerCase();
const onMenu = estado === 'idle' || estado === 'menu_shown';
const ctx = item.context && typeof item.context === 'object' ? item.context : {};

function fold(s) {
  return String(s || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function sqlStr(s) {
